# Reserva Salvaje, area 3 (C5b, contract 48), 28 x 22. column = i, row = j. Area 2's east edge arrives at the WEST edge (spawn `west` (1,10)); the WEST edge (0,10..11) leads back; the NORTH edge (13..14,0) leads to area 4.
# The signature of this area: ROCKY ground: rocks and dry bushes among the tall dry grass, a small pond. The GOLD DENTURES (`dentadura`: in the Reserva Salvaje's area 3) lie on the ground in the south-west corner (1,18).
@map reserva_3
@size 28 22
@interior no
@area reserva
@bg 0
@fill sav
@spawn west 1 10 E
@spawn north 13 1 S
@encounters grass rate=30
  razorfly 27 30 15   # C9 (contract 56): weight lowered to make room for the fill-in (the table still adds up to 100)
  wombamma 27 30 10   # C9 (contract 56): weight lowered to make room for the fill-in (the table still adds up to 100)
  gnucharge 27 30 15   # C9 (contract 56): weight lowered to make room for the fill-in (the table still adds up to 100)
  rockroll 26 29 15
  hatchkip 26 28 10
  lambalm 24 26 5
  jabhawk 27 29 10
  pinecub 26 29 10   # C9 (contract 56): the fill-in of the design notes
  dashkip 26 29 10   # C9 (contract 56): the fill-in of the design notes
@end
# Open ground (contract 63, wild zone): a step onto plain ground (not tall grass, water, a door, a ledge, an arrow floor) rolls this table when rand8 < 8 (8/256 per step).
@open_rate 8
# Roaming wild creatures (contract 55, rollout in 63): 3 creatures of this table wander the open ground (not the tall grass); touching one starts that wild battle.
@roam 3 table=grass period=1800
@encounters water rate=15
  lazatee 25 29 40
  skipgoby 25 29 35
  flopfin 23 27 25
@end
@encounters fish_old
  flopfin 5 5 100
@end
@encounters fish_good rate=128
  flopfin 10 10 25
  skipgoby 10 10 30
  lazatee 10 10 25
  clubrimp 10 10 20
@end
@encounters fish_super
  lazatee 15 22 25
  skipgoby 15 22 20
  clubrimp 15 20 15
  reefling 15 22 20
  flopfin 15 20 20
@end
@legend
  .  tile=sav
  g  tile=dgrass
  a  tile=sav object=acacia_0
  b  tile=sav object=acacia_1
  f  tile=sav object=rfence_i
  F  tile=sav object=rfence_j
  W  tile=canal_o
  T  tile=canal_tr
  r  tile=sav object=rock
  y  tile=sav object=dry_bush
  w  tile=sav
  n  tile=sav
  s  tile=sav object=sign text=rv.sign3 interact=look
  D  tile=sav item=dentadura
  i  item=vit_atk
  c  tile=sav item=disc_41
  H  tile=sav hidden=life_blaze   # hidden (contract 80, hidden items)
